package org.apache.commons.lang3;

import org.openjdk.jmh.annotations.*;
import org.openjdk.jmh.infra.Blackhole;
import java.nio.charset.StandardCharsets;
import java.util.UUID;
import java.util.Arrays;

@State(Scope.Thread)
@BenchmarkMode(Mode.Throughput)
@OutputTimeUnit(TimeUnit.MICROSECONDS)
@Fork(1)
@Warmup(iterations = 5)
@Measurement(iterations = 5)
public class ConversionBenchmark {

    // --- State Initialization ---

    // State for binary array conversions
    @State
    public boolean[] binarySource;
    @State
    public int binarySourcePos;
    @State
    public byte initialByte;
    @State
    public int initialBytePos;
    @State
    public int nBools;

    // State for Hex string conversions
    @State
    public String hexSourceString;
    @State
    public int hexSourcePos;
    @State
    public byte initialByteForHex;
    @State
    public int initialBytePosForHex;
    @State
    public int nHexs;

    // State for Long/Short array conversions
    @State
    public long[] longSourceArray;
    @State
    public int longSourceArrayPos;
    @State
    public long initialLong;
    @State
    public int initialLongPos;
    @State
    public int nLongs;

    @State
    public short[] shortSourceArray;
    @State
    public int shortSourceArrayPos;
    @State
    public short initialShort;
    @State
    public int initialShortPos;
    @State
    public int nShorts;

    @State
    public UUID uuidSource;
    @State
    public byte[] uuidDestinationBuffer;
    @State
    public int uuidDestinationPos;
    @State
    public int uuidBytes;


    @Setup
    public void setup() {
        // 1. Binary/Byte setup (Small, controlled input)
        this.binarySource = new boolean[16];
        Arrays.fill(this.binarySource, true);
        this.binarySourcePos = 0;
        this.initialByte = 0xAA;
        this.initialBytePos = 0;
        this.nBools = 4;

        // 2. Hex setup (String input)
        // 16 hex characters = 64 bits
        this.hexSourceString = "DEADBEEF12345678";
        this.hexSourcePos = 0;
        this.initialByteForHex = (byte) 0x00;
        this.initialBytePosForHex = 0;
        this.nHexs = 8;

        // 3. Long array setup
        this.longSourceArray = new long[4];
        Arrays.fill(this.longSourceArray, 0x11223344L);
        this.longSourceArrayPos = 0;
        this.initialLong = 0xAAAAAAAAAAAAAAAAL;
        this.initialLongPos = 0;
        this.nLongs = 2;

        // 4. Short array setup
        this.shortSourceArray = new short[4];
        Arrays.fill(this.shortSourceArray, (short) 0xBBBB);
        this.shortSourceArrayPos = 0;
        this.initialShort = (short) 0x0000;
        this.initialShortPos = 0;
        this.nShorts = 4;

        // 5. UUID setup
        this.uuidSource = UUID.randomUUID();
        this.uuidDestinationBuffer = new byte[16];
        this.uuidDestinationPos = 0;
        this.uuidBytes = 16;
    }

    // --- Benchmarks ---

    @Benchmark
    public void measureBinaryToByte(Blackhole bh) {
        byte[] result = Conversion.binaryToByte(binarySource, binarySourcePos, initialByte, initialBytePos, nBools);
        bh.consume(result);
    }

    @Benchmark
    public void measureHexToLong(Blackhole bh) {
        long result = Conversion.hexToLong(hexSourceString, hexSourcePos, initialByteForHex, initialBytePosForHex, nHexs);
        bh.consume(result);
    }

    @Benchmark
    public void measureLongToByteArray(Blackhole bh) {
        byte[] result = Conversion.longToByteArray(longSourceArray, longSourceArrayPos, initialByte, initialBytePos, nLongs);
        bh.consume(result);
    }

    @Benchmark
    public void measureShortArrayToInt(Blackhole bh) {
        int result = Conversion.shortArrayToInt(shortSourceArray, shortSourceArrayPos, initialShort, initialShortPos, nShorts);
        bh.consume(result);
    }

    @Benchmark
    public void measureUuidToByteArray(Blackhole bh) {
        byte[] result = Conversion.uuidToByteArray(uuidSource, uuidDestinationBuffer, uuidDestinationPos, uuidBytes);
        bh.consume(result);
    }
}

