package org.apache.commons.lang3;

import org.openjdk.jmh.annotations.*;
import org.openjdk.jmh.infra.Blackhole;
import java.util.UUID;
import java.util.Arrays;
import java.nio.charset.StandardCharsets;

@State(Scope.Thread)
@BenchmarkMode(Mode.Throughput)
@OutputTimeUnit(TimeUnit.MICROSECONDS)
@Fork(1)
@Warmup(iterations = 5)
@Measurement(iterations = 5)
public class ConversionBenchmark {

    // --- State for Binary Conversion Tests ---
    @State
    public boolean[] binaryInput;
    @State
    public boolean[] binaryDest;
    @State
    public int srcPos;
    @State
    public int nBools;

    // --- State for Byte Conversion Tests ---
    @State
    public byte[] byteArrayInput;
    @State
    public byte[] byteArrayDest;
    @State
    public int byteSrcPos;
    @State
    public int byteDstPos;
    @State
    public int byteNBytes;

    // --- State for Int/Long/Short Conversions ---
    @State
    public int[] intArrayInput;
    @State
    public int[] intArrayDest;
    @State
    public int intSrcPos;
    @State
    public int intDstPos;
    @State
    public int intNInts;

    @State
    public long longInput;
    @State
    public long longDest;
    @State
    public int longSrcPos;
    @State
    public int longDstPos;
    @State
    public int longNBools;

    @State
    public short[] shortArrayInput;
    @State
    public short[] shortArrayDest;
    @State
    public int shortSrcPos;
    @State
    public int shortDstPos;
    @State
    public int shortNShorts;

    // --- State for String/UUID Conversions ---
    @State
    public String hexInputString;
    @State
    public String uuidString;
    @State
    public byte[] uuidDest;
    @State
    public int uuidDstPos;
    @State
    public int uuidNBytes;


    @Setup
    public void setup() {
        // Setup for Binary Tests (Input size 16 for testing)
        binaryInput = new boolean[16];
        for (int i = 0; i < 16; i++) {
            binaryInput[i] = (i % 2 == 0);
        }
        binaryDest = new boolean[16];
        srcPos = 0;
        nBools = 16;

        // Setup for Byte Tests (Input size 4 bytes)
        byteArrayInput = new byte[]{0xAA, 0xBB, 0xCC, 0xDD};
        byteArrayDest = new byte[4];
        byteSrcPos = 0;
        byteDstPos = 0;
        byteNBytes = 4;

        // Setup for Int Tests (Input size 1 int)
        intArrayInput = new int[]{0xDEADBEEF};
        intArrayDest = new int[1];
        intSrcPos = 0;
        intDstPos = 0;
        intNInts = 1;

        // Setup for Long Tests
        longInput = 0x123456789ABCDEF0L;
        longDest = 0L;
        longSrcPos = 0;
        longDstPos = 0;
        longNBools = 8;

        // Setup for Short Array Tests (Input size 2 shorts)
        shortArrayInput = new short[]{0x1234, 0x5678};
        shortArrayDest = new short[2];
        shortSrcPos = 0;
        shortDstPos = 0;
        shortNShorts = 2;

        // Setup for String/UUID Tests
        hexInputString = "1A2B3C4D";
        uuidString = UUID.randomUUID().toString();
        uuidDest = new byte[16];
        uuidDstPos = 0;
        uuidNBytes = 16;
    }

    // --- Benchmarks ---

    @Benchmark
    public void measureBinaryToLong(Blackhole bh) {
        // binaryToLong(final boolean[] src, final int srcPos, final long dstInit, final int dstPos, final int nBools)
        long result = Conversion.binaryToLong(binaryInput, srcPos, 0L, 0, nBools);
        bh.consume(result);
    }

    @Benchmark
    public void measureByteArrayToInt(Blackhole bh) {
        // byteArrayToInt(final byte[] src, final int srcPos, final int dstInit, final int dstPos, final int nBytes)
        int result = Conversion.byteArrayToInt(byteArrayInput, byteSrcPos, 0, 0, byteNBytes);
        bh.consume(result);
    }

