    public void measureLongToByteArray(Blackhole bh) {
        // longToByteArray(final long src, final int srcPos, final byte[] dst, final int dstPos, final int nBytes)
        byte[] result = Conversion.longToByteArray(longInput, longSrcPos, new byte[8], 0, 8);
        bh.consume(result);
    }

    @Benchmark
    public void measureIntToShortArray(Blackhole bh) {
        // intToShortArray(final int src, final int srcPos, final short[] dst, final int dstPos, final int nShorts)
        short[] result = Conversion.intToShortArray(intArrayInput[0], intSrcPos, new short[2], shortDstPos, shortNShorts);
        bh.consume(result);
    }

