@Warmup(iterations = 5)
@Measurement(iterations = 5)
public class ConversionBenchmark {

    // --- State for Boolean Array operations ---
    // Input size: 8 bits for basic binary conversions
    @State
    public boolean[] booleanInput8Bits;
    @State
    public boolean[] booleanInput4Bits;
    @State
    public byte[] byteInput8Bytes;
    @State
    public String hexInputString;
    @State
    public int intInputValue;

    @Setup
    public void setup() {
        // Setup Boolean Inputs (8 bits)
        booleanInput8Bits = new boolean[]{true, false, true, false, true, true, false, false};
        // Setup Boolean Inputs (4 bits)
        booleanInput4Bits = new boolean[]{false, true, true, false};

        // Setup Byte Input (8 bytes)
        byteInput8Bytes = new byte[]{0x01, (byte) 0xFF, 0x02, (byte) 0x00, 0x03, (byte) 0x00, 0x04, (byte) 0x00};

        // Setup Hex Input String (16 characters, covering 4 ints)
        hexInputString = "1A2B3C4D5E6F708192A3B4C5D";

        // Setup Integer value
        intInputValue = 42;
    }

    // --- Benchmarks for Boolean Array conversions ---

    @Benchmark
    public void measureBinaryToByte(Blackhole bh) {
        byte result = Conversion.binaryToByte(booleanInput8Bits, 0, (byte) 0x00, 0, 8);
        bh.consume(result);
    }

    @Benchmark
    public void measureBinaryToHexDigit(Blackhole bh) {
        char result = Conversion.binaryToHexDigit(booleanInput8Bits);
        bh.consume(result);
    }

    @Benchmark
    public void measureBinaryToHexDigitPositioned(Blackhole bh) {
        char result = Conversion.binaryToHexDigit(booleanInput8Bits, 4);
        bh.consume(result);
    }

    @Benchmark
    public void measureBinaryToHexDigitMsb0(Blackhole bh) {
        char result = Conversion.binaryToHexDigitMsb0_4bits(booleanInput4Bits);
        bh.consume(result);
    }

    @Benchmark
    public void measureBinaryToHexDigitMsb0Positioned(Blackhole bh) {
        char result = Conversion.binaryToHexDigitMsb0_4bits(booleanInput4Bits, 1);
        bh.consume(result);
    }

    @Benchmark
    public void measureBinaryToInt(Blackhole bh) {
        int result = Conversion.binaryToInt(booleanInput8Bits, 0, 0, 0, 8);
        bh.consume(result);
    }

    @Benchmark
    public void measureBinaryToLong(Blackhole bh) {
        long result = Conversion.binaryToLong(booleanInput8Bits, 0, 0L, 0, 8);
        bh.consume(result);
    }

    @Benchmark
    public void measureBinaryToShort(Blackhole bh) {
        short result = Conversion.binaryToShort(booleanInput4Bits, 0, (short) 0, 0, 4);
        bh.consume(result);
    }

    // --- Benchmarks for Byte Array conversions ---

    @Benchmark
    public void measureByteArrayToInt(Blackhole bh) {
        int result = Conversion.byteArrayToInt(byteInput8Bytes, 0, 0, 0, 8);
        bh.consume(result);
    }

    @Benchmark
    public void measureByteArrayToLong(Blackhole bh) {
        long result = Conversion.byteArrayToLong(byteInput8Bytes, 0, 0L, 0, 8);
        bh.consume(result);
    }

    @Benchmark
    public void measureByteArrayToShort(Blackhole bh) {
