package org.apache.commons.lang3;

import org.openjdk.jmh.annotations.*;
import org.openjdk.jmh.infra.Blackhole;
import java.util.UUID;
import java.util.Arrays;
import java.util.concurrent.TimeUnit;

@State(Scope.Trial)
@BenchmarkMode(Mode.Throughput)
@OutputTimeUnit(TimeUnit.MICROSECONDS)
@Fork(1)
@Warmup(iterations = 5)
@Measurement(iterations = 5)
public class ConversionBenchmark {

    // --- Setup State ---

    // State for boolean array conversions (Length 16 for testing edge cases)
    @State
    public boolean[] boolInput16;

    // State for byte array conversions
    @State
    public byte[] byteArrayInput;

    // State for hexadecimal string conversions
    @State
    public String hexInput;

    // State for large arrays to test boundaries
    @State
    public int[] intArrayInput;
    @State
    public long[] longArrayInput;

    @Setup
    public void setup() {
        // Initialize complex, non-trivial inputs for testing
        this.boolInput16 = new boolean[16];
        Arrays.fill(this.boolInput16, true);

        this.byteArrayInput = new byte[16];
        for (int i = 0; i < 16; i++) {
            this.byteArrayInput[i] = (byte) (i % 256);
        }

        // Hex input string of length 16
        this.hexInput = "123456789ABCDEF";

        this.intArrayInput = new int[8];
        for (int i = 0; i < 8; i++) {
            this.intArrayInput[i] = i * 100 + 5;
        }

        this.longArrayInput = new long[4];
        this.longArrayInput[0] = 0x123456789ABCDEF0000L;
        this.longArrayInput[1] = 0xFFFFFFFFFFFFFFFFL;
        this.longArrayInput[2] = 0xDEADBEEF00000000L;
        this.longArrayInput[3] = 0xABCDEF1234567890L;
    }

    // --- Binary to Hex Digit Benchmarks ---

    @Benchmark
    public char binaryBeMsb0ToHexDigit_NoPos() {
        return Conversion.binaryBeMsb0ToHexDigit(boolInput16);
    }

    @Benchmark
    public char binaryBeMsb0ToHexDigit_WithPos() {
        return Conversion.binaryBeMsb0ToHexDigit(boolInput16, 5);
    }

    @Benchmark
    public char binaryToHexDigit_NoPos() {
        return Conversion.binaryToHexDigit(boolInput16);
    }

    @Benchmark
    public char binaryToHexDigit_WithPos() {
        return Conversion.binaryToHexDigit(boolInput16, 10);
    }

    @Benchmark
    public char binaryToHexDigitMsb0_4bits_NoPos() {
        return Conversion.binaryToHexDigitMsb0_4bits(boolInput16);
    }

    @Benchmark
    public char binaryToHexDigitMsb0_4bits_WithPos() {
        return Conversion.binaryToHexDigitMsb0_4bits(boolInput16, 2);
    }

    // --- Binary/Byte/Long Conversions ---

    @Benchmark
    public byte binaryToByte() {
        return Conversion.binaryToByte(boolInput16, 0, (byte) 0x00, 0, 8);
    }

    @Benchmark
    public long binaryToLong() {
        return Conversion.binaryToLong(boolInput16, 0, 0L, 0, 32);
    }

    @Benchmark
    public int byteArrayToInt() {
        return Conversion.byteArrayToInt(byteArrayInput, 0, 0, 0, 1);
    }

    @Benchmark
    public byte[] longToByteArray() {
        return Conversion.longToByteArray(longArrayInput[0], 0, (byte) 0x00, 0, 8);
    }

    // --- Hex String Conversions ---

    @Benchmark
    public int hexToInt() {
        return Conversion.hexToInt(hexInput, 0, 0, 0, 8);
    }

    @Benchmark
    public long hexToLong() {
        return Conversion.hexToLong(hexInput, 0, 0L, 0, 16);
    }

    @Benchmark
    public int hexToShort() {
        return Conversion.hexToShort(hexInput, 0, (short) 0x0000, 0, 4);
    }

    @Benchmark
    public short hexToByteArray() {
        return Conversion.hexToByteArray(hexInput, 0, (short) 0x0000, 0, 2);
    }

    // --- Complex Array Conversions ---

    @Benchmark
    public long intArrayToLong() {
        return Conversion.intArrayToLong(intArrayInput, 0, 0L, 0, 2);
    }

    @Benchmark
    public shortArrayToInt() {
        short[] shortInput = new short[4];
        Arrays.fill(shortInput, (short) 0xFFFF);
        return Conversion.shortArrayToInt(shortInput, 0, 0, 0, 4);
    }

    @Benchmark
    public long shortArrayToLong() {
        short[] shortInput = new short[4];
        Arrays.fill(shortInput, (short) 0xFFFF);
        return Conversion.shortArrayToLong(shortInput, 0, 0L, 0, 4);
    }
}

