package org.apache.commons.lang3;

import org.apache.commons.lang3.Validate;
import org.openjdk.jmh.annotations.*;
import org.openjdk.jmh.infra.Blackhole;

import java.util.Arrays;
import java.util.Collections;
import java.util.List;
import java.util.Map;
import java.util.Set;
import java.util.concurrent.ConcurrentHashMap;
import java.util.concurrent.CopyOnWriteArrayList;
import java.util.function.Supplier;

@State(Scope.Thread)
@BenchmarkMode(Mode.Throughput)
@OutputTimeUnit(TimeUnit.MICROSECONDS)
@Fork(1)
@Warmup(iterations = 5)
@Measurement(iterations = 5)
public class ValidateBenchmark {

    // --- Setup Data ---

    // Double Inputs
    @State
    public double doubleValue;
    @State
    public double startDouble = 0.1;
    @State
    public double endDouble = 2.1;
    @State
    public double finiteDouble = 3.14159;
    @State
    public double notNaNDouble = 1.0;

    // String Inputs
    @State
    public String inputString = "test_data";
    @State
    public String pattern = "[a-z]+";

    // Collection Inputs
    @State
    public List<Integer> listCollection;
    @State
    public Set<String> setCollection;
    @State
    public Map<String, Integer> mapCollection;
    @State
    public List<String> listWithNulls;

    // Array Inputs
    @State
    public Integer[] arrayWithNulls;
    @State
    public Integer[] nonNullArray;

    // Object Inputs
    @State
    public String okObject = "OK";
    @State
    public String wrongObject = "WRONG";
    @State
    public Class<?> targetClass = String.class;
    @State
    public Class<?> validClass = String.class;


    @Setup
    public void setup() {
        // Initialize collections
        listCollection = Arrays.asList(1, 2, 3, 4, 5);
        setCollection = Set.of("a", "b", "c");
        mapCollection = new ConcurrentHashMap<>();
        mapCollection.put("key1", 10);
        mapCollection.put("key2", 20);
        listWithNulls = new CopyOnWriteArrayList<>(Arrays.asList("x", null, "y", "z"));

        // Initialize arrays
        arrayWithNulls = new Integer[]{1, null, 3, 4};
        nonNullArray = new Integer[]{10, 20, 30};
    }

    // --- Exclusive Between Benchmarks (Double) ---

    @Benchmark
    public Object measureExclusiveBetweenDouble() {
        Validate.exclusiveBetween(startDouble, endDouble, doubleValue);
        return null;
    }

