package org.apache.commons.lang3;

import org.openjdk.jmh.annotations.*;
import org.openjdk.jmh.infra.Blackhole;
import java.util.*;
import java.util.concurrent.TimeUnit;
import java.util.stream.Collectors;
import java.util.stream.IntStream;

@State(Scope.Trial)
@BenchmarkMode(Mode.Throughput)
@OutputTimeUnit(TimeUnit.MICROSECONDS)
@Fork(1)
@Warmup(iterations = 5)
@Measurement(iterations = 5)
public class ValidateBenchmark {

    // State for primitive/double validations
    @State
    public double testDouble1;
    @State
    public double testDouble2;
    @State
    public double testNaN;
    @State
    public double testFinite;

    // State for long validations
    @State
    public long testLong1;
    @State
    public long testLong2;

    // State for string/pattern validations
    @State
    public String testString1;
    @State
    public String testPattern1;
    @State
    public String testBlankString;

    // State for collection/array validations
    @State
    public List<Integer> testCollectionList;
    @State
    public Integer[] testArray;
    @State
    public Map<String, Integer> testMap;

    // State for object/class validations
    @State
    public String testObjectString;
    @State
    public Class<?> testClass1;
    @State
    public Object testInstance;


    @Setup
    public void setup() {
        // Setup Double tests (e.g., for exclusiveBetween and finite)
        testDouble1 = 1.0;
        testDouble2 = 2.0;
        testNaN = Double.NaN;
        testFinite = 5.5;

        // Setup Long tests
        testLong1 = 10L;
        testLong2 = 20L;

        // Setup String tests
        testString1 = "hello world";
        testPattern1 = "[a-z]+";
        testBlankString = "   \t ";

        // Setup Collection tests
        testCollectionList = Arrays.asList(1, 2, 3, 4, 5);
        testArray = new Integer[]{10, 20, 30};
        testMap = new HashMap<>();
        testMap.put("a", 1);
        testMap.put("b", 2);

        // Setup Object tests
        testObjectString = "test value";
        testClass1 = String.class;
        testInstance = "an instance";
    }

    // --- Exclusive Between Benchmarks (Doubles) ---

    @Benchmark
    public void exclusiveBetween_double_standard(Blackhole bh) {
        Validate.exclusiveBetween(testDouble1, testDouble2, testDouble1);
        bh.consume(null);
    }

    @Benchmark
    public void exclusiveBetween_double_with_message(Blackhole bh) {
        Validate.exclusiveBetween(testDouble1, testDouble2, testDouble1, "Error message");
        bh.consume(null);
    }

    @Benchmark
    public void exclusiveBetween_double_long(Blackhole bh) {
        Validate.exclusiveBetween(testLong1, testLong2, testLong1);
        bh.consume(null);
    }

    // --- Finite Benchmarks (Doubles) ---

    @Benchmark
    public void finite_double(Blackhole bh) {
        Validate.finite(testFinite);
        bh.consume(null);
    }

    @Benchmark
    public void notNaN_double(Blackhole bh) {
        Validate.notNaN(testDouble1);
        bh.consume(null);
    }

    // --- Inclusive Between Benchmarks (Doubles) ---

    @Benchmark
    public void inclusiveBetween_double_standard(Blackhole bh) {
        Validate.inclusiveBetween(testDouble1, testDouble2, testDouble1);
        bh.consume(null);
    }

    // --- Class/Object Validations ---

    @Benchmark
    public void isAssignableFrom_standard(Blackhole bh) {
        Validate.isAssignableFrom(testClass1, String.class);
        bh.consume(null);
    }

    @Benchmark
    public void isInstanceOf_standard(Blackhole bh) {
        Validate.isInstanceOf(testClass1, testInstance);
        bh.consume(null);
    }

    // --- String/Pattern Validations ---

    @Benchmark
    public void matchesPattern_valid(Blackhole bh) {
        Validate.matchesPattern(testString1, testPattern1);
        bh.consume(null);
    }

    @Benchmark
    public void matchesPattern_invalid(Blackhole bh) {
        // Use an intentionally invalid pattern/string combination to test exception path
        Validate.matchesPattern("invalid", "[a-z]+");
        bh.consume(null);
    }

    @Benchmark
    public void notBlank_valid(Blackhole bh) {
        Validate.notBlank(testString1);
        bh.consume(null);
    }

    @Benchmark
    public void notBlank_invalid(Blackhole bh) {
        Validate.notBlank(testBlankString, "Must not be blank");
        bh.consume(null);
    }

    // --- Collection/Array Validations ---

    @Benchmark
    public void notEmpty_list_valid(Blackhole bh) {
        Validate.notEmpty(testCollectionList);
        bh.consume(null);
    }

    @Benchmark
    public void notEmpty_map_valid(Blackhole bh) {
        Validate.notEmpty(testMap);
        bh.consume(null);
    }

    @Benchmark
    public void notEmpty_array_valid(Blackhole bh) {
        Validate.notEmpty(testArray);
        bh.consume(null);
    }

    // --- Null/NotNull Validations ---

    @Benchmark
    public void notNull_object_valid(Blackhole bh) {
        Validate.notNull(testInstance);
        bh.consume(null);
    }

    @Benchmark
    public void notNull_object_invalid(Blackhole bh) {
        // Test null input to ensure NPE/exception is thrown
        Validate.notNull(null);
        bh.consume(null);
    }

    // --- True Validations ---

    @Benchmark
    public void isTrue_boolean(Blackhole bh) {
        Validate.isTrue(true);
        bh.consume(null);
    }

    @Benchmark
    public void isTrue_boolean_false(Blackhole bh) {
        // Test false input to ensure exception is thrown
        Validate.isTrue(false);
        bh.consume(null);
    }

    @Benchmark
    public void isTrue_long(Blackhole bh) {
        Validate.isTrue(true, "Long check", testLong1);
        bh.consume(null);
    }

    @Benchmark
    public void isTrue_double(Blackhole bh) {
        Validate.isTrue(true, "Double check", testDouble1);
        bh.consume(null);
    }

    @Benchmark
    public void isTrue_object_variadic(Blackhole bh) {
        Validate.isTrue(false, "Object check", testInstance);
        bh.consume(null);
    }

    // --- Not Empty Variadic Benchmarks (Testing generic/collection methods) ---

    @Benchmark
    public void notEmpty_list_with_message(Blackhole bh) {
        Validate.notEmpty(testCollectionList, "List check");
        bh.consume(null);
    }

    @Benchmark
    public void notEmpty_map_with_message(Blackhole bh) {
        Validate.notEmpty(testMap, "Map check");
        bh.consume(null);
    }

    @Benchmark
    public void notEmpty_array_with_message(Blackhole bh) {
        Validate.notEmpty(testArray, "Array check");
        bh.consume(null);
    }
}

