@Measurement(iterations = 5)
public class ValidateBenchmark {

    // --- State Setup ---
    @State(Scope.Thread)
    public static class State {
        // Double inputs for exclusiveBetween/finite checks
        public double d1 = 1.0;
        public double d2 = 2.0;
        public double d_invalid = 3.5; // Test case for invalid range
        public double d_nan = Double.NaN;
        public double d_infinite = Double.POSITIVE_INFINITY;

        // Long inputs for inclusiveBetween checks
        public long l1 = 1L;
        public long l2 = 10L;
        public long l_invalid = 0L;

        // String inputs for matchesPattern/notBlank checks
        public String s_valid = "hello world";
        public String s_blank = "   ";
        public String s_empty = "";

        // Collection inputs
        public List<Integer> list_valid = Arrays.asList(1, 2, 3);
        public List<Integer> list_empty = Collections.emptyList();
        public List<Integer> list_with_null = Arrays.asList(1, null, 3);

        // Array inputs
        public Integer[] array_valid = {1, 2, 3};
        public Integer[] array_empty = new Integer[0];
        public Integer[] array_with_null = {1, null, 3};

        // Map inputs
        public Map<String, Integer> map_valid = new HashMap<>();
        public Map<String, Integer> map_empty = new HashMap<>();
    }

    // --- Benchmarks ---

    @Benchmark
    public void measureExclusiveBetweenDouble() {
        Validate.exclusiveBetween(State.d1, State.d2, State.d1 + State.d2);
    }

    @Benchmark
    public void measureExclusiveBetweenLong() {
        Validate.exclusiveBetween(State.l1, State.l2, State.l1 + State.l2);
    }

    @Benchmark
    public void measureFiniteDouble() {
        Validate.finite(State.d1);
    }

    @Benchmark
    public void measureFiniteDoubleNaN() {
        Validate.finite(State.d_nan);
    }

    @Benchmark
    public void measureInclusiveBetweenDouble() {
        Validate.inclusiveBetween(State.d1, State.d2, State.d1 + State.d2);
    }

    @Benchmark
    public void measureMatchesPattern() {
        Validate.matchesPattern(State.s_valid, "[a-z]*");
    }

    @Benchmark
    public void measureMatchesPattern_Invalid() {
        // Test case where input fails the pattern check
        Validate.matchesPattern(State.s_blank, "[a-z]*");
    }

    @Benchmark
    public void measureNotBlankString() {
        Validate.notBlank(State.s_valid);
    }

    @Benchmark
    public void measureNotBlankString_Blank() {
        // This should throw an exception, but for throughput benchmarking, we measure the call execution time.
        Validate.notBlank(State.s_blank);
    }

    @Benchmark
