        Validate.notEmpty(State.list_valid);
    }

    @Benchmark
    public void measureNotEmptyCollection_Empty() {
        // This should throw an exception, but we measure the execution path.
        Validate.notEmpty(State.list_empty);
    }

    @Benchmark
    public void measureNotEmptyArray_WithNull() {
        // This should throw an exception, but we measure the execution path.
        Validate.notEmpty(State.array_with_null);
    }

    @Benchmark
    public void measureNotEmptyMap_Empty() {
        // This should throw an exception, but we measure the execution path.
        Validate.notEmpty(State.map_empty);
    }

    @Benchmark
    public void measureNotNullObject() {
        Validate.notNull(State.list_valid);
    }

    @Benchmark
    public void measureIsInstanceOf() {
        // Test case where it should pass
        Validate.isInstanceOf(Integer.class, State.array_valid[0]);
    }

    @Benchmark
    public void measureIsInstanceOf_Mismatch() {
        // Test case where it should fail (Integer vs String)
        Validate.isInstanceOf(String.class, State.array_valid[0]);
    }

    @Benchmark
    public void measureIsTrue_Primitive() {
        Validate.isTrue(true);
    }

    @Benchmark
    public void measureIsTrue_Double() {
        Validate.isTrue(State.d1 > 0.0, "Value > 0", State.d1);
    }

    @Benchmark
    public void measureIsTrue_Long() {
        Validate.isTrue(State.l2 >= 0, "Value >= 0", State.l2);
    }

    @Benchmark
