    @Setup
    public void setup() {
        // Setup String/CharSequence inputs
        inputString = "test string for validation";
        stringList = Arrays.asList("a", "b", "c", "d");

        // Setup Numeric inputs
        validDouble = 1.5;

        // Setup Collection/Array inputs
        intList = Arrays.asList(1, 2, 3, 4, 5);
        integerSet = Set.of(1, 3, 5);
        collection = Arrays.asList("item1", "item2", "item3");

        // Setup Object/Class inputs
        objectList = Arrays.asList("obj1", "obj2");
        targetObject = new Object(); // A simple non-null object
        setClasss();
    }

    private void setClasses() {
        superClass = String.class;
        typeClass = Integer.class;
    }

    // --- Exclusive Between Benchmarks ---

    @Benchmark
    public void benchmarkExclusiveBetweenDouble(Blackhole bh) {
        Validate.exclusiveBetween(0.0, 2.0, validDouble);
        bh.consume(null);
    }

