package org.apache.commons.lang3;

import org.openjdk.jmh.annotations.*;
import org.openjdk.jmh.infra.Blackhole;

import java.util.Arrays;
import java.util.Collection;
import java.util.Collections;
import java.util.List;
import java.util.Map;

@State(Scope.Thread)
@BenchmarkMode(Mode.Throughput)
@OutputTimeUnit(TimeUnit.MICROSECONDS)
@Fork(1)
@Warmup(iterations = 5)
@Measurement(iterations = 5)
public class ValidateBenchmark {

    // State for inputs to drive the benchmarks
    @State
    public List<Double> doubleValues;
    @State
    public List<String> stringValues;
    @State
    public List<Integer> intValues;
    @State
    public List<String> nonBlankStrings;
    @State
    public List<String> nullStrings;
    @State
    public List<String> emptyStrings;
    @State
    public List<Integer> populatedIntArray;
    @State
    public List<Integer> nullIntArray;
    @State
    public List<String> populatedCollection;
    @State
    public List<String> emptyCollection;
    @State
    public List<String> populatedMap;
    @State
    public List<String> emptyMap;

    @Setup
    public void setup() {
        // Setup double values
        doubleValues = Arrays.asList(0.1, 1.0, 2.0, 2.1, 3.0);

        // Setup string values
        stringValues = Arrays.asList("hello", " world ", "", "abc");
        nonBlankStrings = Arrays.asList("a", "b", "c");
        nullStrings = Arrays.asList(null, "test");
        emptyStrings = Arrays.asList("", "  ", "\t");

        // Setup integer values
        intValues = Arrays.asList(1, 5, 10, 20);
        populatedIntArray = Arrays.asList(1, 2, 3);
        nullIntArray = Arrays.asList(1, null, 3);

        // Setup collection values
        populatedCollection = Arrays.asList("A", "B", "C");
        emptyCollection = Collections.emptyList();

        // Setup map values
        populatedMap = Map.of("key1", "val1", "key2", "val2");
        emptyMap = Collections.emptyMap();
    }

    // --- exclusiveBetween Benchmarks ---

    @Benchmark
    public void exclusiveBetweenDouble() {
        Validate.exclusiveBetween(doubleValues.get(0), doubleValues.get(1), doubleValues.get(2));
    }

    @Benchmark
    public void exclusiveBetweenDoubleWithMessage() {
        Validate.exclusiveBetween(doubleValues.get(0), doubleValues.get(1), doubleValues.get(2), "Test msg");
    }

    @Benchmark
    public void exclusiveBetweenLong() {
        Validate.exclusiveBetween(1L, 10L, 5L);
    }

    @Benchmark
    public void exclusiveBetweenLongWithMessage() {
        Validate.exclusiveBetween(1L, 10L, 5L, "Long msg");
    }

    @Benchmark
    public void exclusiveBetweenObjectComparable() {
        // Using a simple double list for Comparable<T> input
        Validate.exclusiveBetween(doubleValues.get(0), doubleValues.get(1), doubleValues.get(2));
    }

    @Benchmark
    public void exclusiveBetweenObjectComparableWithMessage() {
        Validate.exclusiveBetween(doubleValues.get(0), doubleValues.get(1), doubleValues.get(2), "Object msg");
    }

    // --- finite Benchmarks ---

    @Benchmark
    public void finiteDouble() {
        Validate.finite(doubleValues.get(1));
    }

    @Benchmark
    public void finiteDoubleWithMessage() {
        Validate.finite(doubleValues.get(1), "Finite test", 1.0);
    }

    // --- inclusiveBetween Benchmarks ---

    @Benchmark
    public void inclusiveBetweenDouble() {
        Validate.inclusiveBetween(doubleValues.get(0), doubleValues.get(2), doubleValues.get(1));
    }

    @Benchmark
    public void inclusiveBetweenDoubleWithMessage() {
        Validate.inclusiveBetween(doubleValues.get(0), doubleValues.get(2), doubleValues.get(1), "Inclusive msg");
    }

    @Benchmark
    public void inclusiveBetweenLong() {
        Validate.inclusiveBetween(1L, 10L, 5L);
    }

    @Benchmark
    public void inclusiveBetweenLongWithMessage() {
        Validate.inclusiveBetween(1L, 10L, 5L, "Inclusive Long msg");
    }

    // --- isInstanceOf Benchmarks ---

    @Benchmark
    public void isInstanceOfClass() {
        Validate.isInstanceOf(String.class, "a string");
    }

    @Benchmark
    public void isInstanceOfClassWithMessage() {
        Validate.isInstanceOf(String.class, "a string", "Msg");
    }

    @Benchmark
    public void isInstanceOfClassWithValues() {
        Validate.isInstanceOf(String.class, "a string", "Msg", "Value");
    }

    // --- isTrue Benchmarks ---

    @Benchmark
    public void isTrueBoolean() {
        Validate.isTrue(true);
    }

    @Benchmark
    public void isTrueBooleanWithMessage() {
        Validate.isTrue(false, "False test", 1.0);
    }

    @Benchmark
    public void isTrueBooleanWithLong() {
        Validate.isTrue(false, "False test", 10L);
    }

    @Benchmark
    public void isTrueBooleanWithObject() {
        Validate.isTrue(false, "False test", new Object());
    }

    @Benchmark
    public void isTrueBooleanSupplier() {
        Validate.isTrue(false, () -> "Supplier fail");
    }

    // --- matchesPattern Benchmarks ---

    @Benchmark
    public void matchesPatternSimple() {
        Validate.matchesPattern("abc", "[a-z]*");
    }

    @Benchmark
    public void matchesPatternWithMessage() {
        Validate.matchesPattern("abc", "[a-z]*", "Pattern mismatch");
    }

    // --- notEmpty Benchmarks ---

    @Benchmark
    public void notEmptyCollection() {
        Validate.notEmpty(populatedCollection);
    }

    @Benchmark
    public void notEmptyCollectionWithMessage() {
        Validate.notEmpty(populatedCollection, "Collection empty msg");
    }

    @Benchmark
    public void notEmptyMap() {
        Validate.notEmpty(populatedMap);
    }

    @Benchmark
    public void notEmptyMapWithMessage() {
        Validate.notEmpty(populatedMap, "Map empty msg");
    }

    @Benchmark
    public void notEmptyCharSequence() {
        Validate.notEmpty("abc");
    }

    @Benchmark
    public void notEmptyCharSequenceWithMessage() {
        Validate.notEmpty("abc", "String empty msg");
    }

    @Benchmark
    public void notEmptyArray() {
        Validate.notEmpty(populatedIntArray);
    }

    @Benchmark
    public void notEmptyArrayWithMessage() {
        Validate.notEmpty(populatedIntArray, "Array empty msg");
    }

    // --- noNullElements Benchmarks ---

    @Benchmark
    public void noNullElementsIterable() {
        Validate.noNullElements(populatedCollection);
    }

    @Benchmark
    public void noNullElementsIterableWithMessage() {
        Validate.noNullElements(populatedCollection, "Iterable null msg");
    }

    @Benchmark
    public void noNullElementsArray() {
        Validate.noNullElements(populatedIntArray);
    }

    @Benchmark
    public void noNullElementsArrayWithMessage() {
        Validate.noNullElements(populatedIntArray, "Array null msg");
    }
}

