import java.util.TimeZone;
import java.util.concurrent.TimeUnit;

@State(Scope.Benchmark)
@BenchmarkMode(Mode.Throughput)
@OutputTimeUnit(TimeUnit.MICROSECONDS)
@Fork(1)
@Warmup(iterations = 5)
@Measurement(iterations = 5)
public class DurationFormatUtilsBenchmark {

    // State fields populated in @Setup
    private long durationMillis1;
    private long durationMillis2;
    private long startMillis;
    private long endMillis;
    private TimeZone defaultTimeZone;
    private final String formatPattern = "d'd'H'h'm'm's's'";
    private final String isoFormatPattern = DurationFormatUtils.ISO_EXTENDED_FORMAT_PATTERN;

    @Setup
    public void setup() {
        // Setup inputs for duration formatting tests
        durationMillis1 = 123456789L; // A reasonably large number
        durationMillis2 = 100L;       // A small number

        startMillis = 1672531200000L; // Jan 1, 2023 (ms)
        endMillis = 1672531200000L + (3600L * 24L * 7L); // One week later

        defaultTimeZone = TimeZone.getTimeZone("UTC");
    }

    @Benchmark
    public void formatDuration_WithPadding(Blackhole bh) {
        String result = DurationFormatUtils.formatDuration(durationMillis1, formatPattern, true);
        bh.consume(result);
    }

    @Benchmark
    public void formatDuration_NoPadding(Blackhole bh) {
        String result = DurationFormatUtils.formatDuration(durationMillis2, formatPattern, false);
        bh.consume(result);
    }

    @Benchmark
    public void formatDurationHMS(Blackhole bh) {
        String result = DurationFormatUtils.formatDurationHMS(durationMillis1);
        bh.consume(result);
    }

    @Benchmark
    public void formatDurationISO(Blackhole bh) {
        String result = DurationFormatUtils.formatDurationISO(durationMillis1);
        bh.consume(result);
    }

    @Benchmark
    public void formatPeriod_Standard(Blackhole bh) {
        String result = DurationFormatUtils.formatPeriod(startMillis, endMillis, formatPattern);
        bh.consume(result);
    }

    @Benchmark
    public void formatPeriod_WithTimeZone(Blackhole bh) {
        String result = DurationFormatUtils.formatPeriod(startMillis, endMillis, formatPattern, true, defaultTimeZone);
        bh.consume(result);
    }

    @Benchmark
    public void formatPeriodISO(Blackhole bh) {
        String result = DurationFormatUtils.formatPeriodISO(startMillis, endMillis);
        bh.consume(result);
    }

    @Benchmark
    public void formatDurationWords_WithSuppression(Blackhole bh) {
        String result = DurationFormatUtils.formatDurationWords(durationMillis1, true, true);
        bh.consume(result);
    }
}

